    Parse the log file to extract error and warning messages.
    """
    issues_found = []
    pattern = re.compile(r'(ERROR \d{4}|WARNING \d{4})')
    try:
        with open(log_file_path, 'r') as file:
            for line in file:
                match = pattern.search(line)
                if match:
