The function `openPort` takes the protocol ("tcp" or "udp") and the port number as parameters and sets up a socket to listen for incoming connections or datagrams.

```cpp
#include <iostream>
#include <string>
#include <cstring>      // For memset
#include <cstdlib>      // For exit()
#ifdef _WIN32
#include <winsock2.h>
#include <ws2tcpip.h>
#pragma comment(lib, "ws2_32.lib")
#else
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#endif

void initializeSockets() {
#ifdef _WIN32
    WSADATA wsaData;
    int iResult = WSAStartup(MAKEWORD(2,2), &wsaData);
    if (iResult != 0) {
        std::cerr << "WSAStartup failed: " << iResult << std::endl;
        exit(EXIT_FAILURE);
    }
#endif
}

void cleanupSockets() {
#ifdef _WIN32
    WSACleanup();
#endif
}

int openPort(const std::string& protocol, int port) {
    initializeSockets();

    int sockfd;
    int opt = 1;

    if (protocol == "tcp") {
        sockfd = socket(AF_INET, SOCK_STREAM, 0);
    } else if (protocol == "udp") {
        sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    } else {
        std::cerr << "Unsupported protocol: " << protocol << std::endl;
        cleanupSockets();
        return -1;
    }

    if (sockfd < 0) {
        perror("socket creation failed");
        cleanupSockets();
        return -1;
    }

    // Allow reuse of address and port
#ifdef _WIN32
    if (setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR, (const char*)&opt, sizeof(opt)) < 0) {
#else
    if (setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
#endif
        perror("setsockopt(SO_REUSEADDR) failed");
#ifdef _WIN32
        closesocket(sockfd);
#else
        close(sockfd);
#endif
        cleanupSockets();
        return -1;
    }

    sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY; // Listen on all interfaces
    addr.sin_port = htons(port);

    if (bind(sockfd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        perror("bind failed");
#ifdef _WIN32
        closesocket(sockfd);
#else
        close(sockfd);
#endif
        cleanupSockets();
        return -1;
    }

    if (protocol == "tcp") {
        if (listen(sockfd, 5) < 0) {
            perror("listen failed");
#ifdef _WIN32
            closesocket(sockfd);
#else
            close(sockfd);
#endif
            cleanupSockets();
            return -1;
        }
        std::cout << "TCP port " << port << " is open and listening for connections." << std::endl;
    } else {
        std::cout << "UDP port " << port << " is open and ready to receive datagrams." << std::endl;
    }

    // For testing purposes, keep the socket open
    // In a real application, you would handle incoming connections or datagrams here

    // Return the socket descriptor so the caller can manage it (close when done)
    return sockfd;
}

int main() {
    int port = 12345;
    std::string protocol = "tcp";

    int sockfd = openPort(protocol, port);
    if (sockfd < 0) {
        std::cerr << "Failed to open port." << std::endl;
        return EXIT_FAILURE;
    }

    std::cout << "Press Enter to close the port and exit..." << std::endl;
    std::cin.get();

#ifdef _WIN32
    closesocket(sockfd);
#else
    close(sockfd);
#endif
    cleanupSockets();

    return EXIT_SUCCESS;
}
```

### Explanation:
- The function `openPort` creates a socket for the specified protocol and port.
- It sets the socket option `SO_REUSEADDR` to allow quick reuse of the port.
- It binds the socket to all network interfaces on the specified port.
- For TCP, it calls `listen` to start listening for incoming connections.
- For UDP, it just binds the socket to receive datagrams.
- The socket descriptor is returned so the caller can manage the socket lifecycle.
- The example `main` function demonstrates opening a TCP port 12345 and waits for user input before closing the socket and exiting.

### Notes:
- On Windows, you need to link against `ws2_32.lib` and initialize Winsock with `WSAStartup`.
- This example is for testing and demonstration purposes. For production use, you should add proper error handling and possibly multi-threaded connection handling.
- Running this program may require administrative privileges depending on the port number and OS security settings.

